function cuts(){if(!state.duration)return [];if(state.splitMode==='ranges')return state.ranges.map(r=>({...r}));if(state.splitMode==='equal'){const n=finite(state.partCount,1,1000,true);if(state.duration/n<.1)throw Error('Часть не может быть короче 0,1 с.');return Array.from({length:n},(_,i)=>({start:state.duration*i/n,end:state.duration*(i+1)/n}));}const seconds=finite(state.partSeconds,1,86400),count=Math.ceil(state.duration/seconds);if(count>1000)throw Error('Получается больше 1000 частей. Увеличьте длительность.');const result=Array.from({length:count},(_,i)=>({start:i*seconds,end:Math.min(state.duration,(i+1)*seconds)}));if(state.mergeTail&&result.length>1&&result.at(-1).end-result.at(-1).start<seconds*.35){result[result.length-2].end=result.at(-1).end;result.pop();}return result;}
