function validateCue(cue){if(!Number.isFinite(cue.start)||!Number.isFinite(cue.end)||cue.start<0||cue.end<=cue.start||typeof cue.text!=='string'||cue.text.length>2000)throw Error('Проверьте время и текст строки.');}
