function renderSubtitles(){const cues=state.subtitles.cues,pages=Math.max(1,Math.ceil(cues.length/30));subtitlePage=Math.max(0,Math.min(pages-1,subtitlePage));$('subtitlePage').textContent=cues.length?`${cues.length} строк · ${subtitlePage+1}/${pages}`:'Нет строк';$('previousSubtitlePage').disabled=subtitlePage===0;$('nextSubtitlePage').disabled=subtitlePage+1>=pages;const words=cues.filter(c=>c.words?.length).length;$('subtitleHint').textContent=words?`${words} строк с метками слов. После правки текста метки этой строки сбрасываются.`:'Фразовые тайм-коды: подсветка слов недоступна. Для неё нужны метки слов после распознавания речи.';const list=$('subtitleList');list.replaceChildren();cues.slice(subtitlePage*30,subtitlePage*30+30).forEach((cue,j)=>{const i=subtitlePage*30+j,row=document.createElement('div');row.className='subtitle-row';const pair=document.createElement('div');pair.className='field-pair';for(const key of ['start','end']){const inp=document.createElement('input');inp.value=time(cue[key],true);inp.setAttribute('aria-label',`${key==='start'?'Начало':'Конец'} строки ${i+1}`);inp.onchange=handle(()=>{try{const next={...cue,[key]:parseTime(inp.value)};validateCue(next);cue[key]=next[key];delete cue.words;cues.sort((a,b)=>a.start-b.start);renderSubtitles();changed();}catch(error){inp.value=time(cue[key],true);throw error;}});pair.append(inp);}const text=document.createElement('textarea');text.value=cue.text;text.maxLength=2000;text.setAttribute('aria-label','Текст строки '+(i+1));text.oninput=()=>{cue.text=text.value;delete cue.words;changed();};const actions=document.createElement('div');actions.className='subtitle-row-actions';const jump=document.createElement('button');jump.className='text-button';jump.textContent='▶ '+(i+1);jump.onclick=()=>{sourcePreview();video.currentTime=cue.start;requestDraw();};const del=document.createElement('button');del.className='text-button';del.textContent='Удалить';del.onclick=()=>{cues.splice(i,1);renderSubtitles();changed();};actions.append(jump,del);row.append(pair,text,actions);list.append(row);});}
function trackLabel(track){return `${track.index}: ${track.language||'язык не указан'} · ${track.codec||'дорожка'}${track.channels?' · '+track.channels+' кан.':''}${track.default?' · по умолчанию':''}${track.forced?' · forced':''}${track.supported===false?' · графические/не поддерживаются':''}`;}
