async function waitMetadata(media,url){return new Promise((resolve,reject)=>{const clean=()=>{clearTimeout(timer);media.removeEventListener('loadedmetadata',load);media.removeEventListener('error',fail);};const load=()=>{clean();resolve();},fail=()=>{clean();reject(Error('Требуется совместимый предпросмотр.'));},timer=setTimeout(fail,12000);media.addEventListener('loadedmetadata',load,{once:true});media.addEventListener('error',fail,{once:true});media.src=url;media.load();});}
