async function activateAdvert(asset,keep=false){advertAsset=asset;state.advertId=asset.id;if(!keep&&state.advertising.profile==='buba')fitBubaGeometry();$('advertInfo').textContent=`${asset.name||'Ролик'} · ${time(asset.duration,true)} · ${asset.audio?'со звуком':'БЕЗ ЗВУКА'}`;try{await waitMetadata(advertVideo,mediaUrl(asset.id));}catch{$('advertHint').textContent='Ролик не проигрывается в браузере. Проверьте пробный экспорт; исходный файл используется для рендера.';}refreshAdHints();changed();}
function advertArea(){if(!advertAsset)return 0;const g=state.geometry.advert,ratio=advertAsset.width/advertAsset.height;const w=g.fit==='contain'?Math.min(g.w,g.h*ratio):g.w,h=g.fit==='contain'?Math.min(g.h,g.w/ratio):g.h;return w*h/(state.width*state.height)*100;}
