function refreshAdHints(){const ad=state.advertising;$('advertControls').hidden=!ad.enabled;$('advertStart').disabled=ad.profile==='buba';$('advertRepeat').disabled=ad.profile==='buba';$('advertInterval').disabled=ad.profile==='buba';const hint=ad.profile==='floatup'?'FloatUP: начала на 00:20, 01:20, 02:20… итогового клипа. Для клипов короче 60 с проверяйте правила вручную.':ad.profile==='buba'?'MEDIA BUBA: один ролик в середине клипа, по центру экрана; не менее 25% площади, со звуком, скорость до 1,2×. Хромакей включайте только для соответствующего зелёного фона.':'Свои настройки: время начала и повтор — в итоговом клипе.';const area=advertArea();$('advertHint').textContent=hint+(advertAsset?` Площадь изображения до хромакея: ${area.toFixed(1)}%.`:'')+(ad.profile==='buba'&&advertAsset&&area<25?' Соотношение сторон не позволяет занять 25% без обрезки: измените материал или формат холста.':'')+(advertAsset&&!advertAsset.audio?' Внимание: у рекламного ролика нет звуковой дорожки.':'')+(ad.chroma?' Хромакей проверьте пробным экспортом: canvas показывает ролик без удаления фона.':'');}
function syncControls(){for(const [id,value]of [['canvasWidth',state.width],['canvasHeight',state.height],['backgroundBlur',state.background.blur],['backgroundColor',state.background.color],['bannerStart',time(state.banner.start,true)],['bannerEnd',time(state.banner.end,true)],['advertStart',time(state.advertising.start,true)],['advertInterval',state.advertising.interval],['advertSpeed',state.advertising.speed],['subtitleStyle',state.subtitles.style],['subtitleSize',state.subtitles.size],['subtitleColor',state.subtitles.color],['subtitleY',state.subtitles.y],['subtitleOutline',state.subtitles.outline],['partCount',state.partCount],['partSeconds',state.partSeconds],['exportQuality',state.quality],['exportEncoder',state.encoder],['exportFps',state.fps],['speechLanguage',state.speechLanguage],['speechModel',state.speechModel]])$(id).value=value;for(const [id,value]of [['backgroundEnabled',state.background.enabled],['bannerEnabled',state.banner.enabled],['advertRepeat',state.advertising.repeat],['advertChroma',state.advertising.chroma],['subtitlesEnabled',state.subtitles.enabled],['subtitleBackground',state.subtitles.background],['mergeTail',state.mergeTail],['exportZip',state.zip],['exportClean',state.exportClean]])$(id).checked=value;$('adProfile').value=state.advertising.enabled?state.advertising.profile:'none';$('bannerControls').hidden=!state.banner.enabled;$('blurValue').value=state.background.blur+' px';$('subtitleYValue').value=state.subtitles.y+'%';$('resolutionLabel').textContent=`${state.width} × ${state.height}`;document.querySelectorAll('[data-preset]').forEach(b=>b.classList.toggle('active',({vertical:state.width===1080&&state.height===1920,horizontal:state.width===1920&&state.height===1080,square:state.width===1080&&state.height===1080})[b.dataset.preset]));setSplitMode(state.splitMode);refreshAdHints();updateInspector();}
