async function followJob(id,type='render'){type=normalizeJobType(type);if(polling.has(id))return polling.get(id);const run=(async()=>{let failures=0;while(true){let job;try{job=await api('/api/jobs/'+id+'?brief=true',{signal:AbortSignal.timeout(20000)});failures=0;connected=true;$('engineBadge').textContent='Движок подключён';$('engineBadge').classList.add('connected');}catch(error){if(error.status===404){if(state.activeJob?.id===id){state.activeJob=null;persistActive();}throw Error('Задача больше не найдена. Откройте историю и начните её заново.');}failures++;connected=false;$('engineBadge').textContent='Восстанавливаем связь';$('engineBadge').classList.remove('connected');$('jobMessage').textContent='Связь потеряна. Задача может продолжаться. Повторный экспорт заблокирован до восстановления связи.';refreshButtons();await new Promise(resolve=>setTimeout(resolve,Math.min(10000,1000*2**Math.min(failures,4))));continue;}$('jobPanel').hidden=false;$('jobTitle').textContent={render:'Экспорт частей',sample:'Пробный экспорт',preview:'Подготовка предпросмотра',transcribe:'Распознавание речи',extract:'Извлечение субтитров',inspect:'Проверка ссылки',download:'Загрузка видео',overview:'Подготовка шкалы',highlights:'Поиск интересных фрагментов','subtitle-review':'Проверка субтитров','output-check':'Проверка результата'}[type]||'Обработка';$('jobMessage').textContent=job.message||job.error||job.status;$('jobProgress').value=job.progress||0;renderLinks(job.files,$('downloadList'));$('cancelJob').hidden=['done','error','cancelled'].includes(job.status);if(['done','error','cancelled'].includes(job.status)){if(state.activeJob?.id===id){state.activeJob=null;persistActive();changed();}refreshHistory().catch(()=>{});if(job.status==='error')throw Error(job.error||job.message||'Ошибка обработки.');return job;}await new Promise(resolve=>setTimeout(resolve,1200));}})();polling.set(id,run);try{return await run;}finally{polling.delete(id);}}
